+            <g id="grid"></g><g id="fault-region"></g>
+            <path id="band" fill="#83edd1" opacity=".13"/>
+            <path id="dead-path" class="dead-trace"/><path id="truth-path" class="truth-trace"/><path id="a-path" class="a-trace"/><path id="filter-path" class="filter-trace"/>
