+            <g id="robot">
+              <path d="M18-12L108-38V38L18 12Z" fill="url(#beam)"/>
+              <path d="M-25-8h-8v16h8" stroke="#8ca5ae" stroke-width="3" fill="none"/>
+              <rect x="-25" y="-10" width="48" height="20" rx="9" fill="#e5ece6" stroke="#83edd1" stroke-width="2"/>
+              <rect x="-12" y="-15" width="22" height="5" rx="2" fill="#6c999e"/>
+              <circle cx="12" r="4" fill="#071a22" stroke="#659d9b" stroke-width="2"/>
+              <path d="M-14 10v6h12v-6" stroke="#8ca5ae" fill="none" stroke-width="2"/>
+              <circle cx="-17" cy="-2" r="2" fill="#0a5445"/>
+            </g>
+            <text id="robot-label" fill="#a8f4e0" font-size="11" font-family="monospace">B / ESTIMATE</text>
+            <text x="65" y="22" class="axis-label">DEPTH / m ↓</text><text x="805" y="336" class="axis-label" text-anchor="end">TIME / s</text>
+          </svg>
+          <figcaption class="legend"><span class="truth">● Truth</span><span class="measurement">× Depth fix</span><span class="filter">━ Estimate B</span><span class="reference">··· Pinned A</span><span class="dead">┄ Dead reckoning</span><span class="confidence">▰ B ±1.96σ depth</span></figcaption>
+        </figure>
+        <div class="transport">
+          <div class="buttons"><button id="play" class="primary" type="button">▶ Play</button><button id="step" type="button">Step +0.25 s</button><button id="reset" type="button">↺ Reset</button><button id="finish" type="button">To end ↗</button></div>
+          <div class="clock"><span id="time">00.00</span><span> / 60 s</span></div>
