+/* Abyss: one-dimensional, discrete constant-acceleration Kalman model.
+ * Pure functions shared by the browser and numerical tests. No truth in updates. */
+(function (root, factory) {
+  const api = factory();
+  if (typeof module === 'object' && module.exports) module.exports = api;
+  else root.Abyss = api;
+})(typeof window === 'undefined' ? this : window, function () {
+  'use strict';
+  const DT = 0.25, DURATION = 60, INITIAL = [8, 0.12];
+  const DEFAULT = Object.freeze({ q: 0.0036, r: 0.64 });
+  const SCENARIOS = Object.freeze({
+    nominal: { title: 'Quiet water', note: 'Independent acceleration disturbances and unbiased depth fixes. Match R to actual sensor variance, then experiment.' },
+    dropout: { title: 'Lost contact', note: 'No processed depth fixes from 20–36 s. Prediction continues; uncertainty grows until contact returns.' },
+    current: { title: 'Unmodeled current', note: 'An extra downward acceleration of 0.025 m/s² from 18–38 s is hidden from the estimator. This intentionally violates its zero-mean model.' },
+    bias: { title: 'Biased sensor', note: 'Depth fixes gain a +1.8 m offset at 20 s. The filter has no bias state: a narrow band can still miss the truth.' }
+  });
+  function normalGenerator(seed) {
+    let state = seed >>> 0;
+    const uniform = () => {
+      state += 0x6D2B79F5;
+      let t = state;
+      t = Math.imul(t ^ t >>> 15, t | 1);
+      t ^= t + Math.imul(t ^ t >>> 7, t | 61);
+      return ((t ^ t >>> 14) >>> 0) / 4294967296;
+    };
+    return () => Math.sqrt(-2 * Math.log(Math.max(uniform(), 1e-12))) * Math.cos(2 * Math.PI * uniform());
+  }
