+    $('step').disabled = done; $('finish').disabled = done;
+    $('time').textContent = f.t.toFixed(2).padStart(5, '0'); $('scrub').value = cursor; $('scrub-value').textContent = `${fmt(f.t)} s`;
+    $('sigma-value').value = fmt(world.sigma); $('r-value').value = fmt(tuning.r, 4); $('q-value').value = fmt(tuning.q, 4);
+    $('actual-variance').textContent = `Actual variance: ${fmt(world.sigma ** 2, 4)} m²`;
+    $('pin-note').textContent = `A pinned: R ${fmt(pinned.r, 4)} · q ${fmt(pinned.q, 4)}`;
+    $('scenario-note').textContent = E.SCENARIOS[world.scenario].note;
+    for (const [id, v] of [['truth-value', f.truth[0]], ['estimate-value', f.x[0]], ['width-value', f.width], ['error-value', Math.abs(f.error)]]) $(id).innerHTML = `${fmt(v)} <small>m</small>`;
+    $('scene-text').textContent = `At ${fmt(f.t)} s: velocity B ${fmt(f.x[1], 3)} m/s; depth fix ${f.z === null ? 'unavailable at this step' : fmt(f.z) + ' m'}; depth interval [${fmt(f.x[0] - f.width)}, ${fmt(f.x[0] + f.width)}] m. ${Math.abs(f.error) <= f.width ? 'Truth is inside' : 'Truth is outside'} the band.`;
+    $('result-stage').textContent = `${done ? 'MISSION COMPLETE' : 'CUMULATIVE'} · ${fmt(f.t, 1)} s`;
