+  scroll-behavior:smooth
+}
+body {
+  margin:0;
+  background:radial-gradient(ellipse at 18% 0,#12343a 0,transparent 48%),var(--bg);
+  color:var(--ink);
+  line-height:1.55
+}
+a {
+  color:var(--mint);
+  text-underline-offset:4px
+}
+button,input,select {
+  font:inherit
+}
+button,a,input,select,summary {
+  -webkit-tap-highlight-color:transparent
+}
+button,select,input[type=number] {
+  min-height:44px
+}
+button {
+  border:1px solid #38535c;
+  border-radius:5px;
+  background:#112d37;
+  color:var(--ink);
+  padding:9px 13px;
+  cursor:pointer;
+  line-height:1.3;
+  transition:background .15s,border-color .15s
+}
+button:hover {
+  background:#20424b;
+  border-color:var(--mint)
+}
+button:disabled {
+  opacity:.5;
+  cursor:default
+}
+button.primary {
+  background:var(--mint);
+  color:#09252b;
+  border-color:var(--mint);
+  font-weight:700
+}
+button.primary:hover {
+  background:#b6ffe6
+}
+button[aria-pressed=true] {
+  border-color:var(--mint);
+  color:var(--mint);
+  background:#183c40
+}
+a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible {
+  outline:3px solid var(--orange);
+  outline-offset:4px
+}
+.skip {
+  position:absolute;
+  z-index:5;
+  left:16px;
+  top:-100px;
+  background:var(--ink);
+  color:var(--bg);
+  padding:14px
+}
+.skip:focus {
+  top:12px
+}
+.masthead,main,footer {
+  max-width:1392px;
+  margin:auto;
+  padding-inline:40px
+}
+.masthead {
+  height:80px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  border-bottom:1px solid var(--line);
+  gap:20px
+}
+.back {
+  color:var(--muted);
+  text-decoration:none;
+  display:inline-flex;
+  align-items:center;
+  min-height:44px;
+  font-size:13px
+}
+.wordmark {
+  font-size:12px;
+  letter-spacing:.19em;
+  font-weight:700
+}
+.edition,.eyebrow,.small-number {
+  font-family:Consolas,'Courier New',monospace;
+  font-size:10px;
+  letter-spacing:.13em;
+  color:var(--muted)
+}
+.intro {
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap:48px;
+  padding:36px 0 32px
+}
+.eyebrow {
+  margin:0 0 8px
+}
+h1,h2,h3,h4,p {
+  margin-top:0
+}
+h1 {
+  font:normal clamp(64px,7vw,98px)/1 Georgia,serif;
+  letter-spacing:-.07em;
+  margin-bottom:0
+}
+h1 span {
+  color:var(--mint)
+}
+.intro-copy {
+  max-width:420px
+}
+.intro-copy h2 {
+  font-size:23px;
+  font-weight:400;
+  margin-bottom:6px;
+  letter-spacing:-.02em
+}
+.intro-copy p {
+  color:var(--muted);
+  margin-bottom:10px;
+  font-size:14px;
+  max-width:43ch
+}
+.text-link {
+  font-size:12px
+}
+.panel {
+  background:var(--panel);
+  border:1px solid var(--line);
+  border-radius:8px;
+  overflow:hidden
+}
+.panel-heading {
+  display:flex;
+  justify-content:space-between;
+  gap:16px;
+  align-items:center;
+  padding:21px 24px 17px
+}
+.panel-heading h2 {
+  font-size:20px;
+  font-weight:400;
+  letter-spacing:-.025em;
+  margin:0
+}
+.panel-heading h3 {
+  margin:0;
+  font-size:18px;
+  font-weight:400
+}
+.state,.tag {
+  font:10px/1.5 Consolas,monospace;
+  letter-spacing:.08em;
+  color:var(--mint);
+  border:1px solid #386459;
+  padding:5px 9px;
+  border-radius:4px;
+  white-space:nowrap
+}
+.state:before {
+  content:'';
+  display:inline-block;
+  width:5px;
+  height:5px;
+  border-radius:50%;
+  background:var(--mint);
+  margin-right:6px
+}
+.lab {
