+  grid-template-columns:minmax(0,1fr) 318px;
+  gap:20px;
+  scroll-margin-top:16px
+}
+.instrument {
+  min-width:0
+}
+.scenarios {
+  display:flex;
+  gap:6px;
+  margin:0 24px;
+  flex-wrap:wrap
+}
+.scenarios button {
+  font-size:11px;
+  flex:1;
+  padding-inline:8px;
+  white-space:nowrap
+}
+.scenario-note {
+  font-size:12px;
+  color:var(--muted);
+  margin:12px 24px 16px;
+  min-height:38px;
+  max-width:78ch
+}
+.ocean {
+  margin:0
+}
+#scene {
+  display:block;
+  width:100%;
+  height:auto;
+  border-block:1px solid var(--line)
+}
+.axis-label {
+  fill:#a0b7bb;
+  font:10px Consolas,monospace;
+  letter-spacing:.05em
+}
+.grid-line {
+  stroke:#48707d;
+  stroke-opacity:.22;
+  stroke-width:1
+}
+.grid-label {
+  fill:#a5bdc1;
+  font:10px Consolas,monospace
+}
+.truth-trace {
+  fill:none;
+  stroke:#f1f4ed;
+  stroke-width:1.8
+}
+.filter-trace {
+  fill:none;
+  stroke:var(--mint);
+  stroke-width:2.6
+}
+.a-trace {
+  fill:none;
+  stroke:var(--violet);
+  stroke-width:1.8;
+  stroke-dasharray:2 5
+}
+.dead-trace {
+  fill:none;
+  stroke:#9da8b1;
+  stroke-width:1.5;
+  stroke-dasharray:7 5
+}
+.legend {
+  display:flex;
+  flex-wrap:wrap;
+  gap:5px 16px;
+  margin:0;
+  padding:12px 24px;
+  font-size:10px;
+  letter-spacing:.01em;
+  border-bottom:1px solid var(--line)
+}
+.truth {
+  color:#f1f4ed
+}
+.measurement {
+  color:var(--orange)
+}
+.filter,.confidence {
+  color:var(--mint)
+}
+.reference {
+  color:var(--violet)
+}
+.dead {
+  color:#b1bac2
+}
+.transport {
+  display:flex;
+  gap:12px;
+  align-items:center;
+  justify-content:space-between;
+  padding:16px 24px 8px
+}
+.buttons {
+  display:flex;
+  gap:6px;
+  flex-wrap:wrap
+}
+.buttons button {
+  font-size:11px
+}
+.clock {
+  font:13px Consolas,monospace;
+  white-space:nowrap;
+  color:var(--muted)
+}
+.clock span:first-child {
+  font-size:21px;
+  color:var(--ink)
+}
+.scrubber {
+  padding:0 24px 10px;
+  display:grid;
+  grid-template-columns:auto 1fr 56px;
+  gap:12px;
+  align-items:center;
+  font-size:10px;
+  color:var(--muted)
+}
+input[type=range] {
+  appearance:none;
+  -webkit-appearance:none;
+  width:100%;
+  height:44px;
+  background:transparent;
+  cursor:pointer;
+  margin:0;
+  min-width:0
+}
+input[type=range]::-webkit-slider-runnable-track {
+  height:3px;
+  background:#3a5d64;
+  border-radius:3px
+}
+input[type=range]::-moz-range-track {
+  height:3px;
+  background:#3a5d64
+}
+input[type=range]::-webkit-slider-thumb {
+  appearance:none;
+  width:14px;
+  height:18px;
+  border-radius:3px;
+  margin-top:-7px;
+  background:var(--mint);
+  border:2px solid #09252b;
+  box-shadow:0 0 0 1px var(--mint)
+}
+input[type=range]::-moz-range-thumb {
+  width:14px;
+  height:18px;
+  border-radius:3px;
+  background:var(--mint);
+  border:2px solid #09252b
