+.value-line span {
+  font-size:9px;
+  color:var(--muted)
+}
+.settings input[type=range] {
+  height:44px
+}
+.settings #actual-variance {
+  margin-top:-1px
+}
+.seed-row {
+  display:flex;
+  gap:8px;
+  margin-top:6px
+}
+.seed-row input {
+  min-width:0;
+  width:100%;
+  border:1px solid #38535c;
+  border-radius:4px;
+  background:#071a22;
+  color:var(--ink);
+  padding:8px 12px;
+  font-family:Consolas,monospace
+}
+.seed-row button {
+  font-size:11px
+}
+.belief .value-line output {
+  color:var(--mint)
+}
+.tuning-actions {
+  display:grid;
+  gap:8px
+}
+.tuning-actions button {
+  font-size:11px
+}
+.pin-note {
+  color:var(--violet);
+  font:10px Consolas,monospace;
+  margin:12px 0 0
+}
+.desk-note {
+  padding:15px 22px;
+  background:#153139;
+  border-top:1px solid var(--line)
+}
+.small-number {
+  color:var(--orange)
+}
+.desk-note p {
+  font-size:12px;
+  margin:8px 0
+}
+.desk-note .hint {
+  font-size:10px;
+  color:var(--muted)
+}
+.results {
+  margin-top:20px
+}
+.results-layout {
+  display:grid;
+  grid-template-columns:1.2fr 1fr;
+  gap:32px;
+  padding:0 24px 20px
+}
+.table-wrap {
+  min-width:0
+}
+table {
+  border-collapse:collapse;
+  width:100%;
+  font-size:12px;
+  line-height:1.3
+}
+caption {
+  text-align:left;
+  font-size:10px;
+  color:var(--muted);
+  padding-bottom:10px
+}
+th {
+  text-align:left;
+  font-weight:400
+}
+thead th {
+  font:9px Consolas,monospace;
+  color:var(--muted);
+  padding:8px 0
+}
+tbody th,tbody td {
+  padding:9px 0;
+  border-top:1px solid var(--line)
+}
+td {
+  font-family:Consolas,monospace
+}
+.b-row {
+  color:var(--mint)
+}
+.a-row {
+  color:var(--violet)
+}
+.table-wrap .hint {
+  margin:10px 0 0
+}
+.diagnosis {
+  border-left:1px solid var(--line);
+  padding:0 0 0 28px
+}
+.diagnosis .eyebrow {
+  margin-bottom:10px
+}
+.diagnosis h3 {
+  font:24px/1.3 Georgia,serif;
+  margin-bottom:10px
+}
+.diagnosis p:not(.eyebrow) {
+  font-size:13px;
+  color:var(--muted)
+}
+.status-line {
+  display:flex;
+  justify-content:space-between;
+  gap:12px;
+  font:10px Consolas,monospace;
+  border-top:1px solid var(--line);
