+.summary {
+  margin:0;
+  padding:17px 24px;
+  border-top:1px solid #386459;
+  background:#153931;
+  font-size:13px;
+  color:#b5f7db
+}
+.learning {
+  display:grid;
+  grid-template-columns:.8fr 1.2fr;
+  gap:70px;
+  padding:55px 0 35px;
+  scroll-margin-top:24px
