+(function () {
+  'use strict';
+  const E = window.Abyss, $ = id => document.getElementById(id);
+  const world = { seed: 42, sigma: 0.8, scenario: 'nominal' };
+  let tuning = { ...E.DEFAULT }, pinned = { ...E.DEFAULT };
+  let data, b, a, cursor = 0, timer = null;
+  const fmt = (v, n = 2) => v === null || !Number.isFinite(v) ? '—' : v.toFixed(n);
+  const announce = message => { $('announcement').textContent = message; };
+  const svg = (tag, attrs) => {
+    const element = document.createElementNS('http://www.w3.org/2000/svg', tag);
+    Object.entries(attrs).forEach(([key, value]) => element.setAttribute(key, value));
+    return element;
+  };
+  function pause() { if (timer !== null) clearInterval(timer); timer = null; }
+  function compute() { b = E.run(data, tuning); a = E.run(data, pinned); }
+  function fresh() { pause(); cursor = 0; data = E.generate(world); compute(); render(); }
+  function readSeed() {
+    const input = $('seed');
+    if (!input.checkValidity() || input.value === '') { input.reportValidity(); return false; }
+    world.seed = Number(input.value); return true;
+  }
+  function setTuning() {
+    tuning = { q: Number($('q').value), r: Number($('r').value) };
+    compute(); render();
+  }
+  function step() {
+    if (cursor >= data.length - 1) return;
+    cursor++;
+    if (cursor === data.length - 1) { pause(); announce('Mission complete. Read the paired observations and mission summary.'); }
+    render();
+  }
+  function togglePlay() {
+    if (timer !== null) { pause(); render(); announce('Mission paused.'); return; }
+    if (cursor >= data.length - 1) cursor = 0;
+    timer = setInterval(step, 125); // Fixed simulated dt, independent of browser wall-clock jitter.
+    render(); announce('Mission playing at twice real time.');
+  }
+  function plot() {
+    // Fixed mission-wide scale keeps the instrument stable when scrubbing or retuning.
+    const minDepth = Math.min(0, ...b.map(f => f.x[0] - f.width), ...a.map(f => f.x[0]), ...data.filter(f => f.z !== null).map(f => f.z));
+    const maxDepth = Math.max(18, ...b.map(f => f.x[0] + f.width), ...a.map(f => f.x[0]), ...data.map(f => f.truth[0]), ...data.filter(f => f.z !== null).map(f => f.z), ...b.map(f => f.dead[0]));
+    const lo = Math.floor(minDepth / 2) * 2, hi = Math.ceil(maxDepth / 2) * 2;
+    const compact = $('scene').clientWidth < 540, left = compact ? 42 : 65, right = compact ? 326 : 805;
+    $('scene').setAttribute('viewBox', compact ? '0 0 360 350' : '0 0 880 350');
+    $('depth-axis').setAttribute('x', left); $('time-axis').setAttribute('x', right);
+    const x = t => left + t / E.DURATION * (right - left), y = d => 38 + (d - lo) / (hi - lo) * 250;
+    const grid = $('grid'); grid.replaceChildren();
+    for (let i = 0; i <= 4; i++) {
+      const depth = lo + (hi - lo) * i / 4, py = y(depth);
+      grid.append(svg('line', { x1: left, x2: right, y1: py, y2: py, class: 'grid-line' }));
+      const label = svg('text', { x: left - 12, y: py + 3, 'text-anchor': 'end', class: 'grid-label' }); label.textContent = fmt(depth, Number.isInteger(depth) ? 0 : 1); grid.append(label);
+    }
+    for (let t = 0; t <= 60; t += compact ? 15 : 10) {
+      grid.append(svg('line', { x1: x(t), x2: x(t), y1: 38, y2: 288, class: 'grid-line' }));
+      const label = svg('text', { x: x(t), y: 309, 'text-anchor': 'middle', class: 'grid-label' }); label.textContent = t; grid.append(label);
+    }
+    const fault = $('fault-region'); fault.replaceChildren();
+    if (world.scenario !== 'nominal') {
+      const from = world.scenario === 'current' ? 18 : 20, to = world.scenario === 'dropout' ? 36 : world.scenario === 'current' ? 38 : 60;
+      fault.append(svg('rect', { x: x(from), y: 38, width: x(to) - x(from), height: 250, fill: '#f7bf7b', opacity: '.045' }));
+      const label = svg('text', { x: x(from) + 6, y: 31, fill: '#f7bf7b', 'font-size': compact ? 11 : 10, 'font-family': 'monospace' }); label.textContent = world.scenario === 'dropout' ? 'NO FIXES / 20–36 s' : world.scenario === 'current' ? 'CURRENT / 18–38 s' : 'BIAS / +1.8 m'; fault.append(label);
+    }
+    const history = b.slice(0, cursor + 1);
+    const path = (frames, value) => frames.map((f, i) => `${i ? 'L' : 'M'}${fmt(x(f.t))},${fmt(y(value(f)))}`).join(' ');
+    $('truth-path').setAttribute('d', path(history, f => f.truth[0]));
+    $('filter-path').setAttribute('d', path(history, f => f.x[0]));
+    $('dead-path').setAttribute('d', path(history, f => f.dead[0]));
+    $('a-path').setAttribute('d', path(a.slice(0, cursor + 1), f => f.x[0]));
+    $('band').setAttribute('d', path(history, f => f.x[0] - f.width) + history.slice().reverse().map(f => `L${fmt(x(f.t))},${fmt(y(f.x[0] + f.width))}`).join(' ') + 'Z');
+    const fixes = $('fixes'); fixes.replaceChildren();
+    history.filter(f => f.z !== null).forEach(f => {
+      const px = x(f.t), py = y(f.z);
+      fixes.append(svg('path', { d: `M${px - 3},${py - 3}l6,6m-6,0l6,-6` }));
+    });
+    const f = b[cursor], px = x(f.t), py = y(f.x[0]);
+    $('robot').setAttribute('transform', `translate(${px},${py})`);
+    $('truth-dot').setAttribute('transform', `translate(${px},${y(f.truth[0])})`);
+    $('robot-label').setAttribute('x', Math.min(px + 22, right - 80));
+    $('robot-label').setAttribute('y', py - 22);
+    $('cursor-line').setAttribute('x1', px); $('cursor-line').setAttribute('x2', px);
+  }
+  function render() {
+    const f = b[cursor], ref = a[cursor], m = f.metrics, done = cursor === data.length - 1;
+    $('state').textContent = done ? 'COMPLETE' : timer !== null ? 'RUNNING' : cursor ? 'PAUSED' : 'READY';
+    $('play').textContent = timer !== null ? 'Ⅱ Pause' : done ? '▶ Play again' : '▶ Play';
