+    // Joseph: (I-KH) P (I-KH)' + K R K', H=[1,0].
+    const a = 1 - K[0], b = -K[1];
+    const p00 = a * a * P[0][0] + K[0] * K[0] * r;
+    const p01 = a * (b * P[0][0] + P[0][1]) + K[0] * K[1] * r;
+    const p11 = b * b * P[0][0] + b * (P[0][1] + P[1][0]) + P[1][1] + K[1] * K[1] * r;
