+++ b/tests/kalman.test.cjs
@@ -0,0 +1,94 @@
+const assert = require('node:assert/strict');
+const { test } = require('node:test');
+const fs = require('node:fs');
+const path = require('node:path');
+const E = require('../kalman/engine.js');
+const near = (a, b, epsilon = 1e-12) => assert.ok(Math.abs(a - b) < epsilon, `${a} != ${b}`);
+test('exact linear Kalman fixture, including Joseph covariance', () => {
+  const prior = E.predict({ x: [0, 0], P: [[1, 0], [0, 1]] }, 1, 0, 0);
+  assert.deepEqual(prior.x, [0, 0]); assert.deepEqual(prior.P, [[2, 1], [1, 1]]);
+  const f = E.correct(prior, 3, 1);
+  near(f.x[0], 2); near(f.x[1], 1); near(f.K[0], 2 / 3); near(f.K[1], 1 / 3);
+  near(f.P[0][0], 2 / 3); near(f.P[0][1], 1 / 3); near(f.P[1][0], 1 / 3); near(f.P[1][1], 2 / 3);
+});
+test('Q is interval acceleration variance GG transpose and prediction uses known control', () => {
+  assert.deepEqual(E.processCovariance(2, 3), [[12, 12], [12, 12]]);
+  const f = E.predict({ x: [2, 3], P: [[0, 0], [0, 0]] }, 2, 4, 3);
+  assert.deepEqual(f.x, [16, 11]); assert.deepEqual(f.P, [[12, 12], [12, 12]]);
+});
+test('dropout is prediction only and uncertainty grows; return fix contracts it', () => {
+  const frames = E.run(E.generate({ scenario: 'dropout' }));
+  for (const f of frames.filter(f => f.t >= 20 && f.t < 36)) {
+    assert.equal(f.z, null); assert.deepEqual(f.x, f.prior.x); assert.deepEqual(f.P, f.prior.P);
+    assert.equal(f.innovation, null); assert.deepEqual(f.K, [0, 0]);
+  }
+  assert.ok(frames[140].width > frames[76].width * 3);
+  assert.ok(frames[144].P[0][0] < frames[143].P[0][0]);
+});
+test('replay is deterministic; tuning cannot change recorded truth or measurements', () => {
+  const one = E.generate({ seed: 42 }), two = E.generate({ seed: 42 });
+  assert.deepEqual(one, two);
+  const original = JSON.stringify(one);
+  const a = E.run(one), b = E.run(one, { q: 0.04, r: 4 });
+  assert.deepEqual(a.map(f => f.z), b.map(f => f.z));
+  assert.deepEqual(a.map(f => f.truth), b.map(f => f.truth));
+  assert.equal(JSON.stringify(one), original);
+  assert.deepEqual(E.run(two), a);
+  assert.notDeepEqual(a.map(f => f.x), b.map(f => f.x));
+  assert.notDeepEqual(E.generate({ seed: 43 }), one);
+});
+test('truth has no effect on filter state, gain or covariance', () => {
+  const data = E.generate();
+  const tampered = data.map(f => ({ ...f, truth: [9000, -9000] }));
+  const a = E.run(data), b = E.run(tampered);
+  a.forEach((f, i) => { assert.deepEqual(f.x, b[i].x); assert.deepEqual(f.P, b[i].P); assert.deepEqual(f.K, b[i].K); });
+});
+test('faults occur at the documented times without shifting seeded noise', () => {
+  const normal = E.generate(), bias = E.generate({ scenario: 'bias' }), dropout = E.generate({ scenario: 'dropout' }), current = E.generate({ scenario: 'current' });
+  normal.forEach((f, i) => {
+    assert.deepEqual(f.truth, bias[i].truth); assert.deepEqual(f.truth, dropout[i].truth);
+    if (f.z !== null) near(bias[i].z - f.z, f.t >= 20 ? 1.8 : 0);
+    if (f.t < 20 || f.t >= 36) assert.equal(f.z, dropout[i].z);
+    if (f.t < 18) assert.deepEqual(f.truth, current[i].truth);
+  });
+  assert.ok(current[152].truth[0] > normal[152].truth[0]);
+});
+test('covariance stays finite, symmetric and PSD over 100,000 steps including prolonged dropout', () => {
+  let f = { x: [0, 0], P: [[1, 0], [0, 1]] };
+  for (let i = 0; i < 100000; i++) {
+    f = E.correct(E.predict(f, .25, Math.sin(i) * .1, i % 2 ? .06 : 0), i % 700 < 500 ? null : Math.sin(i / 100), i % 2 ? .01 : 9);
+    assert.ok(f.x.every(Number.isFinite)); assert.ok(f.P.flat().every(Number.isFinite));
+    near(f.P[0][1], f.P[1][0]); assert.ok(f.P[0][0] >= 0 && f.P[1][1] >= 0);
+    assert.ok(f.P[0][0] * f.P[1][1] - f.P[0][1] ** 2 >= -1e-9);
+  }
+});
+test('fixed seed RMSE agrees with independently summed errors and yields meaningful nominal performance', () => {
+  for (const scenario of Object.keys(E.SCENARIOS)) {
+    const frames = E.run(E.generate({ seed: 42, scenario })), last = frames.at(-1), fixes = frames.filter(f => f.z !== null);
+    const independent = Math.sqrt(frames.slice(1).reduce((sum, f) => sum + (f.x[0] - f.truth[0]) ** 2, 0) / 240);
+    near(last.metrics.filter, independent);
+    near(last.metrics.raw, Math.sqrt(fixes.reduce((sum, f) => sum + (f.z - f.truth[0]) ** 2, 0) / fixes.length));
+    assert.equal(last.t, 60); assert.equal(frames.length, 241);
+    assert.ok(last.metrics.filter > 0 && Number.isFinite(last.metrics.dead));
+    if (scenario === 'nominal') assert.ok(last.metrics.filter < last.metrics.raw);
+    console.log(`${scenario}: B=${last.metrics.filter.toFixed(6)}, raw=${last.metrics.raw.toFixed(6)}, DR=${last.metrics.dead.toFixed(6)}, coverage=${last.metrics.coverage.toFixed(2)}%, fixes=${fixes.length}`);
+  }
+});
+test('all mission scenarios and tuning boundaries have finite states and nonnegative covariance', () => {
+  for (const scenario of Object.keys(E.SCENARIOS)) for (const q of [0, .0036, .06]) for (const r of [.0001, .0025, .64, 9]) {
+    for (const f of E.run(E.generate({ seed: 42, sigma: 2, scenario }), { q, r })) {
+      assert.ok(f.x.every(Number.isFinite) && Number.isFinite(f.width));
+      assert.ok(f.P[0][0] >= 0 && f.P[1][1] >= 0);
+      assert.ok(f.P[0][0] * f.P[1][1] - f.P[0][1] ** 2 >= -1e-10);
+    }
+  }
+});
+test('all portfolio HTML local script and stylesheet references still exist', () => {
+  const root = path.resolve(__dirname, '..');
+  const pages = ['index.html','about/index.html','experience/index.html','projects/index.html','secret/index.html','circular/index.html','cad-machining/index.html','upload/index.html','upload/viewer.html','stephen-ai/index.html','kalman/index.html'];
+  for (const page of pages) for (const [, resource] of fs.readFileSync(path.join(root, page), 'utf8').matchAll(/(?:href|src)="([^"?#]+\.(?:css|js))"/g)) {
+    // viewer.html is served by the Worker at /uploads/{id}/, not /upload/viewer.html.
+    const servedDirectory = page === 'upload/viewer.html' ? 'uploads/fixture' : path.dirname(page);
+    if (!/^https?:/.test(resource)) assert.ok(fs.existsSync(path.resolve(root, servedDirectory, resource)), `${page}: ${resource}`);
+  }
+});
