+    const cross = P[0][1] + h * P[1][1] + Q[0][1];
+    return {
+      x: [p + h * v + 0.5 * h * h * u, v + h * u],
+      P: [[P[0][0] + h * (P[0][1] + P[1][0]) + h * h * P[1][1] + Q[0][0], cross], [cross, P[1][1] + Q[1][1]]]
+    };
+  }
+  function correct(prior, z, r) {
+    if (z === null) return { x: prior.x.slice(), P: prior.P.map(row => row.slice()), K: [0, 0], innovation: null, S: null };
+    const P = prior.P, S = P[0][0] + r, K = [P[0][0] / S, P[1][0] / S];
+    const innovation = z - prior.x[0];
+    // Joseph: (I-KH) P (I-KH)' + K R K', H=[1,0].
+    const a = 1 - K[0], b = -K[1];
+    const p00 = a * a * P[0][0] + K[0] * K[0] * r;
+    const p01 = a * (b * P[0][0] + P[0][1]) + K[0] * K[1] * r;
+    const p11 = b * b * P[0][0] + b * (P[0][1] + P[1][0]) + P[1][1] + K[1] * K[1] * r;
+    return { x: [prior.x[0] + K[0] * innovation, prior.x[1] + K[1] * innovation], P: [[p00, p01], [p01, p11]], K, innovation, S };
+  }
+  function generate({ seed = 42, sigma = 0.8, scenario = 'nominal' } = {}) {
+    if (!SCENARIOS[scenario] || !Number.isFinite(sigma) || sigma < 0) throw new Error('Invalid world configuration');
+    const random = normalGenerator(seed), frames = [{ t: 0, truth: INITIAL.slice(), u: 0, z: null, event: 'Initial state' }];
+    let [p, v] = INITIAL;
+    for (let i = 1; i <= DURATION / DT; i++) {
+      const t = i * DT, u = command(t - DT);
+      const current = scenario === 'current' && t >= 18 && t < 38 ? 0.025 : 0;
+      const acceleration = u + random() * 0.06 + current;
+      p += v * DT + acceleration * DT * DT / 2;
+      v += acceleration * DT;
+      // Draw sensor noise on every tick so missing fixes do not shift the RNG stream.
+      const noise = random() * sigma;
+      const lost = scenario === 'dropout' && t >= 20 && t < 36;
+      const biased = scenario === 'bias' && t >= 20;
+      const z = i % 4 === 0 && !lost ? p + noise + (biased ? 1.8 : 0) : null;
+      frames.push({ t, truth: [p, v], u, z, event: lost ? 'Contact lost · prediction only' : biased ? 'Sensor bias +1.8 m' : current ? 'Downward current active' : z === null ? 'Between fixes · prediction only' : 'Depth fix received' });
+    }
+    return frames;
+  }
+  function run(data, { q, r } = DEFAULT) {
+    if (!Number.isFinite(q) || q < 0 || !Number.isFinite(r) || r <= 0) throw new Error('Q must be nonnegative and R positive');
+    let state = { x: INITIAL.slice(), P: [[1, 0], [0, 0.04]] };
+    let dead = INITIAL.slice(), rawSum = 0, rawCount = 0, sum = 0, deadSum = 0, covered = 0;
+    return data.map((frame, i) => {
+      let prior = state, result = { ...state, K: [0, 0], innovation: null, S: null };
+      if (i) {
+        prior = predict(state, DT, frame.u, q);
+        // The estimator receives only commands and processed scalar fixes.
+        result = correct(prior, frame.z, r);
+        state = result;
+        dead = [dead[0] + DT * dead[1] + DT * DT / 2 * frame.u, dead[1] + DT * frame.u];
+        const error = state.x[0] - frame.truth[0];
+        sum += error * error;
+        deadSum += (dead[0] - frame.truth[0]) ** 2;
+        if (Math.abs(error) <= 1.96 * Math.sqrt(state.P[0][0])) covered++;
+        if (frame.z !== null) { rawSum += (frame.z - frame.truth[0]) ** 2; rawCount++; }
+      }
+      return { ...frame, ...result, prior, dead: dead.slice(), error: result.x[0] - frame.truth[0], width: 1.96 * Math.sqrt(result.P[0][0]),
+        metrics: { filter: i ? Math.sqrt(sum / i) : null, dead: i ? Math.sqrt(deadSum / i) : null, raw: rawCount ? Math.sqrt(rawSum / rawCount) : null, rawCount, coverage: i ? 100 * covered / i : null } };
+    });
+  }
+  return { DT, DURATION, INITIAL, DEFAULT, SCENARIOS, normalGenerator, processCovariance, predict, correct, generate, run };
+});
