--- /dev/null
+++ b/kalman/preview.cjs
@@ -0,0 +1,18 @@
+// Optional local static preview; no dependencies. Worker-backed uploads need their own preview.
+const http = require('node:http');
+const fs = require('node:fs');
+const path = require('node:path');
+const root = path.resolve(__dirname, '..');
+const types = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.svg': 'image/svg+xml', '.png': 'image/png', '.jpg': 'image/jpeg' };
+http.createServer((req, res) => {
+  let pathname;
+  try { pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname); }
+  catch { res.writeHead(400).end(); return; }
+  let file = path.resolve(root, '.' + pathname);
+  if (file !== root && !file.startsWith(root + path.sep)) { res.writeHead(403).end(); return; }
+  try {
+    if (fs.statSync(file).isDirectory()) file = path.join(file, 'index.html');
+    res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
+    fs.createReadStream(file).pipe(res);
+  } catch { res.writeHead(404).end('Not found'); }
+}).listen(8313, '127.0.0.1', () => console.log('Abyss preview: http://localhost:8313/kalman/'));
